package com.tripmateai.service.impl; import com.tripmateai.ai.AiProviderClient; import com.tripmateai.dto.request.ai.AiTripPlanRequest; import com.tripmateai.dto.response.ai.*; import com.tripmateai.entity.*; import com.tripmateai.enums.ActivityType; import com.tripmateai.exception.*; import com.tripmateai.mapper.TripMapper; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.AiTripPlannerService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class AiTripPlannerServiceImpl implements AiTripPlannerService {private final AiProviderClient provider;private final DestinationRepository destinations;private final TripRepository trips;private final ItineraryRepository itineraries;private final ActivityRepository activities; private User current(){var p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(p instanceof UserPrincipal x))throw new UnauthorizedException("Authentication required");return x.user();} @Transactional public AiTripPlanResponse generate(AiTripPlanRequest r){var destination=destinations.findById(r.destinationId()).orElseThrow(()->new ResourceNotFoundException("Destination not found"));var days=provider.generate(r,destination);validate(days,r.numberOfDays());var trip=new Trip();trip.setUser(current());trip.setDestination(destination);trip.setTripName(r.tripName());trip.setStartDate(r.startDate());trip.setEndDate(r.startDate().plusDays(r.numberOfDays()-1L));trip.setBudget(r.budget());trip.setNumberOfTravelers(r.numberOfTravelers());trip.setPreferences(r.preferences()==null?new HashSet<>():new HashSet<>(r.preferences()));trip=trips.save(trip);for(var day:days){var itinerary=new Itinerary();itinerary.setTrip(trip);itinerary.setDayNumber(day.dayNumber());itinerary.setTitle(day.title());itinerary=itineraries.save(itinerary);int order=1;for(var planned:day.activities()){var a=new Activity();a.setItinerary(itinerary);a.setTitle(planned.title());a.setDescription(planned.description());a.setLocation(planned.location());a.setStartTime(planned.startTime());a.setEndTime(planned.endTime());a.setEstimatedCost(planned.estimatedCost());a.setType(ActivityType.OTHER);a.setSortOrder(order++);activities.save(a);}}return new AiTripPlanResponse(TripMapper.toResponse(trip),days);} private void validate(List<AiItineraryDayResponse> days,int expected){if(days==null||days.size()!=expected)throw new BadRequestException("AI response must contain the requested number of days");var numbers=new HashSet<Integer>();for(var day:days){if(day==null||day.dayNumber()==null||day.dayNumber()<1||day.dayNumber()>expected||!numbers.add(day.dayNumber())||day.activities()==null)throw new BadRequestException("AI response contains invalid itinerary days");for(var a:day.activities()){if(a==null||a.title()==null||a.title().isBlank()||a.estimatedCost()!=null&&a.estimatedCost().signum()<0||a.startTime()!=null&&a.endTime()!=null&&a.endTime().isBefore(a.startTime()))throw new BadRequestException("AI response contains an invalid activity");}}}}
